submissions.repair-original-cache-eviction-pinned-by:
def solve(data):
    entries = data['entries']
    remaining = sum(entry['size'] for entry in entries)
    eligible = [entry for entry in entries if not entry['pinned']]
    eligible.sort(key=lambda entry: (entry['last_used'], entry['id']))
    evicted = []
    for entry in eligible:
        if remaining <= data['capacity']:
            break
        evicted.append(entry['id'])
        remaining -= entry['size']
    return {'evicted': evicted, 'remaining_bytes': remaining}

submissions.repair-original-cap-net-cancellation-ref:
def solve(data):
    if data['booking_state'] != 'cancelled' or data['hours_notice'] < 24:
        return 0
    charges = sum(row['cents'] for row in data['charges'] if row['state'] == 'posted')
    concessions = sum(row['cents'] for row in data['concessions'] if row['state'] == 'posted')
    allowance = charges if data['hours_notice'] >= 48 else charges // 2
    return min(data['cap_cents'], max(0, allowance - concessions))

submissions.repair-original-compact-print-color-runs:
def solve(data):
    result = []
    for run in data['runs']:
        if run['state'] == 'deleted':
            continue
        color = run['color']
        if result and result[-1]['color'] == color:
            result[-1]['pixels'] += run['pixels']
        else:
            result.append({'color': color, 'pixels': run['pixels']})
    return result

